import{_ as e,a0 as p,w as r,s as o,I as s,x as n,a1 as i,A as l,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"採用 snaps 為 Linux 社區構建 Slack | LCTT x X-CMD","titleTemplate":false,"description":"採用 snaps 為 Linux 社區構建 Slack | LCTT (201902) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"採用 snaps 為 Linux 社區構建 Slack | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"採用 snaps 為 Linux 社區構建 Slack | LCTT (201902) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201902/20180206 Building Slack for the Linux community and adopting snaps","title":"採用 snaps 為 Linux 社區構建 Slack","tag":"201902","desc":""},"relativePath":"201902/20180206 Building Slack for the Linux community and adopting snaps.md","filePath":"[post].md"}'),u={name:"201902/20180206 Building Slack for the Linux community and adopting snaps.md"};function h(m,a,x,k,b,f){const t=p("Link");return r(),o("div",null,[a[19]||(a[19]=s("h1",{id:"採用-snaps-為-linux-社區構建-slack",tabindex:"-1"},[n("採用 snaps 為 Linux 社區構建 Slack "),s("a",{class:"header-anchor",href:"#採用-snaps-為-linux-社區構建-slack","aria-label":"Permalink to “採用 snaps 為 Linux 社區構建 Slack”"},"​")],-1)),a[20]||(a[20]=s("p",null,[s("img",{src:"https://insights.ubuntu.com/wp-content/uploads/a115/Slack_linux_screenshot@2x-2.png",alt:""})],-1)),s("p",null,[a[2]||(a[2]=n("作為一個被數以百萬計用户使用的企業級軟件平台，",-1)),i(t,{href:"https://slack.com/"},{default:l(()=>[...a[0]||(a[0]=[n("Slack",-1)])]),_:1}),a[3]||(a[3]=n(" 可以讓各種規模的團隊和企業有效地溝通。Slack 通過在一個單一集成環境中與其它軟件工具無縫銜接，為一個組織內的通訊、信息和項目提供了一個易於接觸的檔案館。儘管自從誕生後 Slack 就在過去四年中快速成長，但是他們負責該平台的 Windows、MacOS 和 Linux 桌面的工程師團隊僅由四人組成。我們採訪了這個團隊的主任工程師 Felix Rieseberg（他負責追蹤",-1)),i(t,{href:"https://insights.ubuntu.com/2018/01/18/canonical-brings-slack-to-the-snap-ecosystem/"},{default:l(()=>[...a[1]||(a[1]=[n("上月首次發佈的 Slack snap",-1)])]),_:1}),a[4]||(a[4]=n("，LCTT 譯註：原文發佈於 2018.2），來了解更多有關該公司對於 Linux 社區的態度，以及他們決定構建一個 snap 軟件包的原因。",-1))]),s("ul",null,[s("li",null,[i(t,{href:"https://snapcraft.io/slack/"},{default:l(()=>[...a[5]||(a[5]=[n("安裝 Slack snap",-1)])]),_:1})])]),a[21]||(a[21]=d('<h3 id="你們能告訴我們更多關於已發佈的-slack-snap-的信息嗎" tabindex="-1">你們能告訴我們更多關於已發佈的 Slack snap 的信息嗎？ <a class="header-anchor" href="#你們能告訴我們更多關於已發佈的-slack-snap-的信息嗎" aria-label="Permalink to “你們能告訴我們更多關於已發佈的 Slack snap 的信息嗎？”">​</a></h3><p>作為發佈給 Linux 社區的一種新形式，我們上月發佈了我們的第一個 snap。在企業界，我們發現人們更傾向於以一種相對於個人消費者來説較慢的速度來採用新科技，因此我們將會在未來繼續提供 .deb 形式的軟件包。</p><h3 id="你們覺得-linux-社區會對-slack-有多大的興趣呢" tabindex="-1">你們覺得 Linux 社區會對 Slack 有多大的興趣呢？ <a class="header-anchor" href="#你們覺得-linux-社區會對-slack-有多大的興趣呢" aria-label="Permalink to “你們覺得 Linux 社區會對 Slack 有多大的興趣呢？”">​</a></h3><p>我很高興在所有的平台上人們都對 Slack 的興趣越來越大。因此，很難説來自 Linux 社區的興趣和我們大體上所見到的興趣有什麼區別。當然，不管用户們在什麼平台上面工作，滿足他們對我們都是很重要的。我們有一個專門負責 Linux 的測試工程師，並且我們同時也會盡全力提供最好的用户體驗。</p><p>只是我們發現總體相對於 Windows 來説，為 Linux 搭建 snap 略微有點難度，因為我們是在一個較難以預測的平台上工作——而這正是 Linux 社區之光照耀的領域。在彙報程序缺陷以及尋找程序崩潰原因方面，我們有相當多極有幫助的用户。</p><h3 id="你們是如何得知-snap-的" tabindex="-1">你們是如何得知 snap 的？ <a class="header-anchor" href="#你們是如何得知-snap-的" aria-label="Permalink to “你們是如何得知 snap 的？”">​</a></h3><p>Canonical 公司的 Martin Wimpress 接觸了我，並向我解釋了 snap 的概念。説實話儘管我也用 Ubuntu 但最初我還是遲疑的，因為它看起來像需要搭建與維護的另一套標準。然而，一當我瞭解到其中的好處之後，我確信這是一筆值得的投入。</p><h3 id="snap-的什麼方面吸引了你們並使你們決定投入其中" tabindex="-1">snap 的什麼方面吸引了你們並使你們決定投入其中？ <a class="header-anchor" href="#snap-的什麼方面吸引了你們並使你們決定投入其中" aria-label="Permalink to “snap 的什麼方面吸引了你們並使你們決定投入其中？”">​</a></h3><p>毫無疑問，我們決定搭建 snap 最重要的原因是它的更新特性。在 Slack 上我們大量運用了網頁技術，這些技術反過來也使得我們提供大量的特性——比如將 YouTube 視頻或者 Spotify 播放列表集成在 Slack 中。與瀏覽器十分相似，這意味着我們需要頻繁更新應用。</p><p>在 MacOS 和 Windows 上，我們已經有了一個專門的自動更新器，甚至無需用户關注更新。任何形式的中斷都是一種我們需要避免的煩惱，哪怕是為了更新。因此通過 snap 自動化的更新就顯得更加無縫和便捷。</p><h3 id="相比於其它形式的打包方式-構建-snap-感覺如何-將它與現有的設施和流程集成在一起有多簡便呢" tabindex="-1">相比於其它形式的打包方式，構建 snap 感覺如何？將它與現有的設施和流程集成在一起有多簡便呢？ <a class="header-anchor" href="#相比於其它形式的打包方式-構建-snap-感覺如何-將它與現有的設施和流程集成在一起有多簡便呢" aria-label="Permalink to “相比於其它形式的打包方式，構建 snap 感覺如何？將它與現有的設施和流程集成在一起有多簡便呢？”">​</a></h3><p>就 Linux 而言，我們尚未嘗試其它的“新”打包方式，但我們遲早會的。鑑於我們的大多數用户都使用 Ubuntu，snap 是一個自然的選擇。同時 snap 在其它發行版上同樣也可以使用，這也是一個巨大的加分項。Canonical 正將 snap 做到跨發行版，而不是僅僅集中在 Ubuntu 上，這一點我認為是很好的。</p><p>搭建 snap 極其簡單，我們有一個創建安裝器和軟件包的統一流程，我們的 snap 創建過程就是從一個 .deb 軟件包炮製出一個 snap。對於其它技術而言，有時候我們為了支持構建鏈而先打造一個內部工具。但是 snapcraft 工具正是我們需要的東西。在整個過程中 Canonical 的團隊非常有幫助，因為我們一路上確實碰到了一些問題。</p><h3 id="你們覺得-snap-商店是如何改變用户們尋找、安裝你們軟件的方式的呢" tabindex="-1">你們覺得 snap 商店是如何改變用户們尋找、安裝你們軟件的方式的呢？ <a class="header-anchor" href="#你們覺得-snap-商店是如何改變用户們尋找、安裝你們軟件的方式的呢" aria-label="Permalink to “你們覺得 snap 商店是如何改變用户們尋找、安裝你們軟件的方式的呢？”">​</a></h3><p>Slack 真正的獨特之處在於人們不僅僅是碰巧發現它，他們從別的地方知道它並積極地試圖找到它。因此儘管我們已經有了相當高的覺悟，我希望對於我們的用户來説，在商店中可以獲得 snap 能夠讓安裝過程變得簡單一點。</p><p>我們總是盡力為用户服務。當我們覺得它比其他安裝方式更好，我們就會向用户更多推薦它。</p><h3 id="通過使用-snap-而不是為其它發行版打包-你期待或者已經看到的節省是什麼" tabindex="-1">通過使用 snap 而不是為其它發行版打包，你期待或者已經看到的節省是什麼？ <a class="header-anchor" href="#通過使用-snap-而不是為其它發行版打包-你期待或者已經看到的節省是什麼" aria-label="Permalink to “通過使用 snap 而不是為其它發行版打包，你期待或者已經看到的節省是什麼？”">​</a></h3><p>我們希望 snap 可以給予我們的用户更多的便利，並確保他們能夠更加喜歡使用 Slack。在我們看來，鑑於用户們不必被困在之前的版本，這自然而然地解決了許多問題，因此 snap 可以讓我們在客户支持方面節約時間。snap 對我們來説也是一個額外的加分項，因為我們能有一個可供搭建的平台，而不是替換我們現有的東西。</p><h3 id="如果存在的話-你們正使用或者準備使用邊緣-edge-、測試-beta-、候選-candidate-、穩定-stable-中的哪種發行頻道" tabindex="-1">如果存在的話，你們正使用或者準備使用邊緣 (edge)、測試 (beta)、候選 (candidate)、穩定 (stable) 中的哪種發行頻道？ <a class="header-anchor" href="#如果存在的話-你們正使用或者準備使用邊緣-edge-、測試-beta-、候選-candidate-、穩定-stable-中的哪種發行頻道" aria-label="Permalink to “如果存在的話，你們正使用或者準備使用邊緣 (edge)、測試 (beta)、候選 (candidate)、穩定 (stable) 中的哪種發行頻道？”">​</a></h3><p>我們開發中專門使用邊緣 (edge) 頻道以與 Canonical 團隊合作。為 Linux 打造的 Slack 總體仍處於測試 (beta) 頻道中。但是長遠來看，擁有不同頻道的選擇十分有意思，同時能夠提早一點為感興趣的客户發佈版本也肯定是有好處的。</p><h3 id="你們如何認為將軟件打包成一個-snap-能夠幫助用户-你們從用户那邊得到了什麼反饋嗎" tabindex="-1">你們如何認為將軟件打包成一個 snap 能夠幫助用户？你們從用户那邊得到了什麼反饋嗎？ <a class="header-anchor" href="#你們如何認為將軟件打包成一個-snap-能夠幫助用户-你們從用户那邊得到了什麼反饋嗎" aria-label="Permalink to “你們如何認為將軟件打包成一個 snap 能夠幫助用户？你們從用户那邊得到了什麼反饋嗎？”">​</a></h3><p>對我們的用户來説一個很大的好處是安裝和更新總體來説都會變得簡便一點。長遠來看，問題是“那些安裝 snap 的用户是不是比其它用户少碰到一些困難？”，我十分期望 snap 自帶的依賴關係能夠使其變成可能。</p><h3 id="你們對剛使用-snap-的新用户們有什麼建議或知識呢" tabindex="-1">你們對剛使用 snap 的新用户們有什麼建議或知識呢？ <a class="header-anchor" href="#你們對剛使用-snap-的新用户們有什麼建議或知識呢" aria-label="Permalink to “你們對剛使用 snap 的新用户們有什麼建議或知識呢？”">​</a></h3><p>我會推薦從 Debian 軟件包來着手搭建你們的 snap ——那出乎意料得簡單。這同樣也縮小了範圍，避免變得不堪重負。這隻需要投入相當少的時間，並且很大可能是一筆值得的投入。同樣如果你們可以的話，儘量試着找到 Canonical 的人員來協作——他們擁有了不起的工程師。</p><h3 id="對於開發來説-你們在什麼地方看到了最大的機遇" tabindex="-1">對於開發來説，你們在什麼地方看到了最大的機遇？ <a class="header-anchor" href="#對於開發來説-你們在什麼地方看到了最大的機遇" aria-label="Permalink to “對於開發來説，你們在什麼地方看到了最大的機遇？”">​</a></h3><p>我們現在正一步步來，先是讓人們接受 snap，再從那裏開始搭建。正在使用 snap 的人們將會感到更加穩健，因為他們將會得益於最新的更新。</p><hr>',27)),s("p",null,[a[7]||(a[7]=n("via: ",-1)),i(t,{href:"https://insights.ubuntu.com/2018/02/06/building-slack-for-the-linux-community-and-adopting-snaps/"},{default:l(()=>[...a[6]||(a[6]=[n("https://insights.ubuntu.com/2018/02/06/building-slack-for-the-linux-community-and-adopting-snaps/",-1)])]),_:1})]),s("p",null,[a[11]||(a[11]=n("作者：",-1)),i(t,{href:"https://insights.ubuntu.com/author/sarahfd/"},{default:l(()=>[...a[8]||(a[8]=[n("Sarah",-1)])]),_:1}),a[12]||(a[12]=n(" 譯者：",-1)),i(t,{href:"https://github.com/tomjlw"},{default:l(()=>[...a[9]||(a[9]=[n("tomjlw",-1)])]),_:1}),a[13]||(a[13]=n(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:l(()=>[...a[10]||(a[10]=[n("wxy",-1)])]),_:1})]),s("p",null,[a[16]||(a[16]=n("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[14]||(a[14]=[n("LCTT",-1)])]),_:1}),a[17]||(a[17]=n(" 原創編譯，",-1)),i(t,{href:"https://linux.cn/"},{default:l(()=>[...a[15]||(a[15]=[n("Linux中國",-1)])]),_:1}),a[18]||(a[18]=n(" 榮譽推出",-1))])])}const L=e(u,[["render",h]]);export{g as __pageData,L as default};
